package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.List;
import java.util.Set;
import org.apache.commons.lang.StringUtils;
import org.apache.commons.lang.Validate;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_prepend_TriageGen0Test {

    @Test
    public void testPrepend_NullHtml() {
        Element element = new Element(new Tag("div"), "baseUri");
        try {
            element.prepend(null);
            fail("Expected NullPointerException");
        } catch (NullPointerException e) {
            // Expected
        }
    }

    @Test
    public void testPrepend_EmptyHtml() {
        Element element = new Element(new Tag("div"), "baseUri");
        Element result = element.prepend("");
        assertTrue("Expected result to be instance of Element", result instanceof Element);
        assertTrue("Expected result to be same instance as input", result == element);
    }

    @Test
    public void testPrepend_SimpleHtml() {
        Element element = new Element(new Tag("div"), "baseUri");
        Element result = element.prepend("<p>test</p>");
        assertTrue("Expected result to be instance of Element", result instanceof Element);
        assertTrue("Expected result to not be same instance as input", result != element);
        assertEquals("Expected result to have one child", 1, result.children().size());
        assertEquals("Expected result to have correct child tag name", "p", result.children().get(0).tagName());
        assertEquals("Expected result to have correct child text", "test", result.children().get(0).text());
    }

    @Test
    public void testPrepend_ComplexHtml() {
        Element element = new Element(new Tag("div"), "baseUri");
        Element result = element.prepend("<p>test</p><span>more test</span>");
        assertTrue("Expected result to be instance of Element", result instanceof Element);
        assertTrue("Expected result to not be same instance as input", result != element);
        assertEquals("Expected result to have two children", 2, result.children().size());
        assertEquals("Expected result to have correct child tag names", "p", result.children().get(0).tagName());
        assertEquals("Expected result to have correct child text", "test", result.children().get(0).text());
        assertEquals("Expected result to have correct child tag names", "span", result.children().get(1).tagName());
        assertEquals("Expected result to have correct child text", "more test", result.children().get(1).text());
    }

    @Test
    public void testPrepend_DuplicateHtml() {
        Element element = new Element(new Tag("div"), "baseUri");
        Element result = element.prepend("<p>test</p><p>test</p>");
        assertTrue("Expected result to be instance of Element", result instanceof Element);
        assertTrue("Expected result to not be same instance as input", result != element);
        assertEquals("Expected result to have two children", 2, result.children().size());
        assertEquals("Expected result to have correct child tag names", "p", result.children().get(0).tagName());
        assertEquals("Expected result to have correct child text", "test", result.children().get(0).text());
        assertEquals("Expected result to have correct child tag names", "p", result.children().get(1).tagName());
        assertEquals("Expected result to have correct child text", "test", result.children().get(1).text());
    }

    @Test
    public void testPrepend_NullBaseUri() {
        Element element = new Element(new Tag("div"), null);
        try {
            element.prepend("<p>test</p>");
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            // Expected
        }
    }

    @Test
    public void testPrepend_BaseUriNotString() {
        Element element = new Element(new Tag("div"), "baseUri");
        try {
            element.prepend("<p>test</p>");
            fail("Expected ClassCastException");
        } catch (ClassCastException e) {
            // Expected
        }
    }
}
